import { chromium } from '@playwright/test';
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:1440,height:1080},deviceScaleFactor:1});
page.on('pageerror', e => console.log('PAGE ERROR:', e.message));
await page.goto('http://localhost:3000');
await page.getByRole('heading',{name:'Currently reading',exact:true}).waitFor();
await page.evaluate(() => document.fonts.ready);
await page.screenshot({path:'/tmp/littleleaf-desktop.png',fullPage:true});
console.log('Desktop overflow:', await page.evaluate(() => document.documentElement.scrollWidth > innerWidth));
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/littleleaf-mobile.png',fullPage:true});
console.log('Mobile overflow:', await page.evaluate(() => document.documentElement.scrollWidth > innerWidth));
await browser.close();
JS"

