# Littleleaf

A small, account-free reading tracker built with React, Vite, and a Node/Express server. Add books, keep notes, move them between reading and finished shelves, and share an individual book at `/books/:id`.

## Run locally

Requires Node.js 20.19+ (or 22.12+).

```sh
npm install
npm run dev
```

Open `http://localhost:3000`. To run a production build:

```sh
npm run build
npm start
```

## Your books

Books are saved on the server in `data/books.json`. The file is created on first launch with eight editable example books. To start with an empty shelf, set `SEED_BOOKS=false` before the first launch. An existing file is always kept, including an empty shelf.

```sh
SEED_BOOKS=false npm run dev
```

You can set `BOOKS_FILE` to an absolute path to choose another location, and `PORT` to change the default port. Writes are serialized and saved through an atomic rename so overlapping requests do not lose updates. Back up the JSON file to back up your shelf. Use one server process per file.

Deploy the Node server on a host with a persistent disk, or set `BOOKS_FILE` to a file on a persistent volume. An ephemeral/serverless filesystem will not retain the shelf across deployments. A shared link uses the app's current address; recipients need to be able to reach that address. There are no accounts or permissions, so anyone who can access the app can view and edit the shelf and its notes.

## Checks

```sh
npm test
npm run build
npm run test:e2e
```

Store tests cover persistence across restarts, simultaneous writes, validation, deletion, and preservation of damaged files. Browser checks cover adding, editing, finishing, sharing, removing, search, sorting, and mobile navigation against the production build. Run `npx playwright install chromium` once before browser checks.

The sample covers are served locally from Open Library cover images. Lora and DM Sans are served locally from Google Fonts. Custom covers and the reading illustration are rendered in the app, so adding books needs no third-party service.
import { mkdir, readFile, writeFile, rename } from "node:fs/promises";
import { dirname } from "node:path";
import { randomUUID } from "node:crypto";

export const colors = ["sand", "sage", "lavender", "rose", "peach"];
export class ValidationError extends Error {}
export class NotFoundError extends Error {}

function validate(fields, partial = false) {
  const result = {};
  for (const [field, limit] of [
    ["title", 200],
    ["author", 200],
    ["notes", 20000],
  ]) {
    if (partial && !(field in fields)) continue;
    const value = fields[field] ?? (field === "notes" ? "" : undefined);
    if (
      typeof value !== "string" ||
      value.length > limit ||
      (field !== "notes" && !value.trim())
    ) {
      throw new ValidationError(
        `${field[0].toUpperCase() + field.slice(1)} must be ${field === "notes" ? "text" : "non-empty text"} under ${limit + 1} characters.`,
      );
    }
    result[field] = field === "notes" ? value : value.trim();
  }
  if (!partial || "status" in fields) {
    result.status = fields.status ?? "reading";
    if (!["reading", "finished"].includes(result.status))
      throw new ValidationError("Choose reading or finished.");
  }
  if (!partial || "color" in fields) {
    result.color = fields.color ?? "sage";
    if (!colors.includes(result.color))
      throw new ValidationError("Choose a valid cover color.");
  }
  return result;
}

export function createBookStore(file, initialBooks = []) {
  let queue = Promise.resolve();
  const initialized = (async () => {
    await mkdir(dirname(file), { recursive: true });
    try {
      await readFile(file, "utf8");
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
      await writeFile(file, `${JSON.stringify(initialBooks, null, 2)}\n`, {
        flag: "wx",
      }).catch((error) => {
        if (error.code !== "EEXIST") throw error;
      });
    }
  })();
  async function read() {
    await initialized;
    const books = JSON.parse(await readFile(file, "utf8"));
    if (!Array.isArray(books))
      throw new Error("Books file must contain an array.");
    for (const book of books) {
      if (!book || typeof book.id !== "string")
        throw new Error("Invalid book in books file.");
      validate(book);
    }
    return books;
  }
  function mutate(operation) {
    const task = queue.then(async () => {
      const books = await read();
      const result = operation(books);
      const temporaryFile = `${file}.${randomUUID()}.tmp`;
      await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}\n`);
      await rename(temporaryFile, file);
      return result;
    });
    queue = task.catch(() => {});
    return task;
  }
  return {
    async list() {
      await queue;
      return read();
    },
    add(fields) {
      const data = validate(fields);
      return mutate((books) => {
        const now = new Date().toISOString();
        const book = {
          id: randomUUID(),
          ...data,
          cover: null,
          createdAt: now,
          finishedAt: data.status === "finished" ? now : null,
        };
        books.unshift(book);
        return book;
      });
    },
    update(id, fields) {
      const data = validate(fields, true);
      return mutate((books) => {
        const book = books.find((book) => book.id === id);
        if (!book) throw new NotFoundError("This book could not be found.");
        if (data.status && data.status !== book.status)
          book.finishedAt =
            data.status === "finished" ? new Date().toISOString() : null;
        Object.assign(book, data);
        return book;
      });
    },
    remove(id) {
      return mutate((books) => {
        const index = books.findIndex((book) => book.id === id);
        if (index === -1)
          throw new NotFoundError("This book could not be found.");
        books.splice(index, 1);
      });
    },
  };
}

