test("add a book, keep notes, finish it, share its direct page, edit and remove it", async ({
  page,
  context,
}) => {
  await context.grantPermissions(["clipboard-read", "clipboard-write"]);
  await page.goto("/");
  await expect(
    page.getByText("Every shelf starts with a story."),
  ).toBeVisible();
  await page
    .getByRole("button", { name: "Add a book", exact: true })
    .first()
    .click();
  await page.getByLabel("Book title").fill("A Room of One’s Own");
  await page.getByLabel("Author", { exact: true }).fill("Virginia Woolf");
  await page.getByLabel("My notes").fill("A quiet afternoon read.");
  await page.getByRole("button", { name: "lavender cover" }).click();
  await page.getByRole("button", { name: "Add to my shelf" }).click();
  await expect(page.getByRole("dialog")).not.toBeVisible();
  await page
    .getByRole("link", { name: "A Room of One’s Own", exact: true })
    .click();
  await expect(
    page.getByRole("heading", { name: "A Room of One’s Own" }),
  ).toBeVisible();
  const bookUrl = page.url();
  await page.getByRole("button", { name: "Edit notes", exact: true }).click();
  await page
    .getByLabel("My notes")
    .fill("A quiet afternoon read.\nA thought worth keeping.");
  await page.getByRole("button", { name: "Save notes" }).click();
  await page
    .getByRole("button", { name: "Mark as finished", exact: true })
    .click();
  await expect(
    page.getByRole("button", { name: "Move to reading" }),
  ).toBeVisible();
  await page.reload();
  await expect(
    page.getByText("A quiet afternoon read.\nA thought worth keeping."),
  ).toBeVisible();
  await expect(
    page.getByRole("button", { name: "Move to reading" }),
  ).toBeVisible();
  await page.getByRole("button", { name: "Share book", exact: true }).click();
  await expect(page.getByLabel("Link to this book")).toHaveValue(bookUrl);
  await page.getByRole("button", { name: "Copy", exact: true }).click();
  await expect(page.getByRole("button", { name: "Copied!" })).toBeVisible();
  expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(
    bookUrl,
  );
  const sharedPage = await context.newPage();
  await sharedPage.goto(bookUrl);
  await expect(
    sharedPage.getByRole("heading", { name: "A Room of One’s Own" }),
  ).toBeVisible();
  await expect(
    sharedPage.getByText("by Virginia Woolf", { exact: true }),
  ).toBeVisible();
  await expect(
    sharedPage.getByText("A quiet afternoon read.\nA thought worth keeping."),
  ).toBeVisible();
  await sharedPage.close();
  await page.getByRole("button", { name: "Close dialog" }).click();
  await page.getByRole("button", { name: "Edit book details" }).click();
  await page.getByLabel("Book title").fill("A Room of One’s Own — reread");
  await page.getByRole("button", { name: "Save changes" }).click();
  await expect(
    page.getByRole("heading", { name: "A Room of One’s Own — reread" }),
  ).toBeVisible();
  await page.getByRole("link", { name: "Back to my library" }).click();
  await page.getByRole("tab", { name: "Finished" }).click();
  await expect(
    page.getByRole("link", {
      name: "A Room of One’s Own — reread",
      exact: true,
    }),
  ).toBeVisible();
  await page
    .getByRole("button", { name: "Options for A Room of One’s Own — reread" })
    .click();
  await page.getByRole("button", { name: "Remove book", exact: true }).click();
  await page
    .getByRole("dialog")
    .getByRole("button", { name: "Remove book", exact: true })
    .click();
  await expect(
    page.getByText("The best stories take their time."),
  ).toBeVisible();
  await page.goto(bookUrl);
  await expect(
    page.getByRole("heading", { name: "This page has wandered off." }),
  ).toBeVisible();
});

